<?php declare(strict_types=1);require __DIR__.'/../../includes/bootstrap.php';require_once __DIR__.'/../../includes/services.php';require_student();verify_csrf($_POST['csrf_token']??null);$uid=(int)current_user()['user_id'];$type=$_POST['type']??'expense';$amount=(float)($_POST['amount']??0);$date=$_POST['transaction_date']??'';$desc=trim((string)($_POST['description']??''));$cat=(int)($_POST['category_id']??0);if(!in_array($type,['income','expense'],true)||$amount<=0||!valid_date($date)||$desc===''){flash('transaction_error','Complete all required fields.');redirect('student/add-transaction.php');}$category=find_category($cat,$uid,$type);if(!$category){flash('transaction_error','Choose a valid category.');redirect('student/add-transaction.php');}$ai=suggest_category($uid,$desc,$type);try{$s=db()->prepare('INSERT INTO transactions(user_id,category_id,amount,type,description,ai_suggested_category_id,ai_confidence,source,transaction_date) VALUES(?,?,?,?,?,?,?,?,?)');$s->execute([$uid,$cat,$amount,$type,$desc,$ai['category_id']??null,$ai['confidence']??null,'manual',$date]);$tid=(int)db()->lastInsertId();if($ai){db()->prepare('INSERT INTO ai_category_suggestions(transaction_id,user_id,description_text,suggested_category_id,accepted_category_id,confidence,was_overridden,resolved_at) VALUES(?,?,?,?,?,?,?,CURRENT_TIMESTAMP)')->execute([$tid,$uid,$desc,$ai['category_id'],$cat,$ai['confidence'],$ai['category_id']!=$cat]);}if(!empty($_POST['make_recurring'])){$freq=$_POST['frequency']??'monthly';$next=$date;if($freq==='weekly')$next=date('Y-m-d',strtotime($date.' +7 days'));elseif($freq==='daily')$next=date('Y-m-d',strtotime($date.' +1 day'));elseif($freq==='yearly')$next=date('Y-m-d',strtotime($date.' +1 year'));else$next=date('Y-m-d',strtotime($date.' +1 month'));db()->prepare('INSERT INTO recurring_transactions(user_id,category_id,type,amount,description,frequency,starts_on,next_run_date) VALUES(?,?,?,?,?,?,?,?)')->execute([$uid,$cat,$type,$amount,$desc,$freq,$date,$next]);}add_activity($uid,'create','transaction',$tid,['amount'=>$amount,'type'=>$type]);ensure_budget_alerts($uid);flash('success','Transaction added successfully.');redirect('student/transactions.php');}catch(Throwable$e){error_log($e->getMessage());flash('transaction_error','Could not save the transaction.');redirect('student/add-transaction.php');}